mapper.select:
SELECT g.goods_code as goodsCode, g.goods_name as goodsName, SUM(i.quantity) as totalQuantity, SUM(i.amount) as totalAmount FROM biz_sale_item i INNER JOIN biz_sale_order o ON i.order_id = o.id INNER JOIN biz_goods g ON i.goods_id = g.id WHERE o.deleted = 0 AND o.status >= 1
AND DATE(o.create_time) >= #{startDate}
AND DATE(o.create_time) <= #{endDate}
GROUP BY g.id, g.goods_code, g.goods_name ORDER BY totalAmount DESC LIMIT #{limit}

SELECT g.goods_code as goodsCode, g.goods_name as goodsName, SUM(i.quantity) as quantity, SUM(i.amount) as saleAmount, SUM(i.quantity * COALESCE(i.cost_price, g.purchase_price)) as costAmount, SUM(i.amount) - SUM(i.quantity * COALESCE(i.cost_price, g.purchase_price)) as profit, ROUND((SUM(i.amount) - SUM(i.quantity * COALESCE(i.cost_price, g.purchase_price))) / SUM(i.amount) * 100, 2) as profitRate FROM biz_sale_item i INNER JOIN biz_sale_order o ON i.order_id = o.id INNER JOIN biz_goods g ON i.goods_id = g.id WHERE o.deleted = 0 AND o.status >= 2
AND DATE(o.ship_time) >= #{startDate}
AND DATE(o.ship_time) <= #{endDate}
GROUP BY g.id, g.goods_code, g.goods_name HAVING SUM(i.amount) > 0 ORDER BY profit DESC

SELECT COALESCE(SUM(i.quantity * COALESCE(i.cost_price, g.purchase_price)), 0) FROM biz_sale_item i INNER JOIN biz_sale_order o ON i.order_id = o.id INNER JOIN biz_goods g ON i.goods_id = g.id WHERE o.deleted = 0 AND o.status >= 2
AND DATE(o.ship_time) >= #{startDate}
AND DATE(o.ship_time) <= #{endDate}
